import{z as B,x as d,o as i,c as p,q as r,j as n,D as t,d as E,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"可靠性与图形化缺陷","description":"","frontmatter":{"title":"可靠性与图形化缺陷","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reliability-patterning-defects.md","filePath":"litho/reliability-patterning-defects.md","lastUpdated":1791063341000}'),A={name:"litho/reliability-patterning-defects.md"};function D(h,a,T,c,m,u){const l=d("Mermaid");return i(),p("div",null,[a[2]||(a[2]=r('<h1 id="可靠性与图形化缺陷" tabindex="-1">可靠性与图形化缺陷 <a class="header-anchor" href="#可靠性与图形化缺陷" aria-label="Permalink to &quot;可靠性与图形化缺陷&quot;">​</a></h1><div class="epigraph"><p>探针绿灯的管芯仍可能在电迁徙、击穿或经时击穿上死：尖角、via 覆盖不足、侧壁损伤把图形化误差写成寿命。</p><footer>—— 对照 BEOL 可靠性（EM、TDDB）与图形化几何的公开讨论</footer></div><p><a href="/litho/parametric-yield-cd">上一课</a>处理出厂参数。缺口是时间：尖的金属线端、via 落在金属边、刻蚀损伤的栅侧壁，出货时电学可过，寿命不够。本课钉图形化缺陷的可靠性面。TEM/FIB 如何取证，留给<a href="/litho/failure-analysis-tem-fib">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>电迁徙（EM）吃电流密度，线窄、via 偏、尖角会局部加热和空洞。TDDB 吃介质厚度与电场，金属间距与线边缘粗糙等效减薄。栅氧化或 HKMG 侧壁损伤来自过刻与离子。这些很少被光学缺陷检测当 killer，因为「还连着」。</p><p><span class="marginnote">术语翻译：电迁徙（EM）是大电流把金属原子慢慢「冲走」——线越窄电流密度越高，死得越快；TDDB 是介质在电场下经时击穿，「经时」意味着不是一通电就坏，而是像绷太久的橡皮筋，用着用着才断。</span></p><p>缺口是<strong>可靠性规格要回写设计规则与 OPC 目标</strong>，不是再讲失效物理全书。tip-to-tip 与 via enclosure 有一截就是寿命，不只是可印。LRC 覆盖检查是可靠性代理。</p><h3 id="筛选盖不住几何" tabindex="-1">筛选盖不住几何 <a class="header-anchor" href="#筛选盖不住几何" aria-label="Permalink to &quot;筛选盖不住几何&quot;">​</a></h3><p>HTOL 筛选能抓早期夭折，吃不掉整批系统性的偏 via。系统图形问题应用 OPC/规则消灭，不能靠老化筛选当良率工具。</p><p><span class="marginnote">EPE 预算若只对准功能连通，可靠性余量可能已被吃光。签核要声明寿命目标是否在 PV-band 内。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 EM/TDDB 设计规则映射到 CD、间距、enclosure、侧壁角。热区：线端、via 链、最小间距密布。计量：AEI 剖面、覆盖、LER 低频。与钝化课：弓形侧壁改电场。与助推器：BPR 深槽的填充虚空是可靠性，不只是刻蚀。</p><p>PV-band 签核若不含寿命代理，功能绿灯会在 HTOL 上翻车。规则修订应同时请可靠性签字，而不是只请光刻。BEOL 可靠性公开讨论把几何当场强与电流密度的前置，本课把前置写进 LRC。</p>',13)),(i(),n(s,null,{default:t(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIFE%5B%22%E5%AF%BF%E5%91%BD%E7%9B%AE%E6%A0%87%EF%BC%88HTOL%20%E5%B9%B4%E6%95%B0%EF%BC%89%22%5D%20--%3E%20MAP%5B%22%E7%BF%BB%E8%AF%91%E6%88%90%E5%87%A0%E4%BD%95%E4%BB%A3%E7%90%86%22%5D%0A%20%20MAP%20--%3E%20T2T%5B%22tip-to-tip%20%E9%97%B4%E8%B7%9D%22%5D%0A%20%20MAP%20--%3E%20ENC%5B%22via%20enclosure%22%5D%0A%20%20MAP%20--%3E%20SW%5B%22%E4%BE%A7%E5%A3%81%E8%A7%92%20%2F%20LER%22%5D%0A%20%20T2T%20--%3E%20LRC%5B%22LRC%20%2F%20OPC%20%E7%9B%AE%E6%A0%87%22%5D%0A%20%20ENC%20--%3E%20LRC%0A%20%20SW%20--%3E%20LRC%0A%20%20LRC%20--%3E%20PV%5B%22PV-band%20%E5%90%AB%E5%AF%BF%E5%91%BD%E4%BB%A3%E7%90%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「老化筛选把坏的剔掉就行」。HTOL 筛选只能抓早期夭折个体，整批系统性的偏 via 是设计与工艺问题——靠筛选救等于拿良率填坑，正解是让规则与 OPC 在源头消灭这类几何。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"功能良率看开/短路阈值；可靠性看场强与电流密度的连续函数。PV-band 外沿的几何可能功能过、寿命短。随机缺孔若「勉强打开」，电阻高且 EM 弱。故随机窗与可靠性窗可能比均值 CD 窗更严——要交三张窗。",-1)),(i(),n(s,null,{default:t(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEO%5B%22CD%20%E9%97%B4%E8%B7%9D%20enclosure%20%E5%B0%96%E8%A7%92%22%5D%20--%3E%20EM%5B%22%E7%94%B5%E8%BF%81%E5%BE%99%22%5D%0A%20%20GEO%20--%3E%20TDDB%5B%22%E4%BB%8B%E8%B4%A8%E5%87%BB%E7%A9%BF%22%5D%0A%20%20ET%5B%22%E4%BE%A7%E5%A3%81%E6%8D%9F%E4%BC%A4%22%5D%20--%3E%20REL%5B%22%E5%AF%BF%E5%91%BD%22%5D%0A%20%20EM%20--%3E%20REL%0A%20%20TDDB%20--%3E%20REL%0A%20%20REL%20--%3E%20DR%5B%22%E8%A7%84%E5%88%99%20%2F%20LRC%20%E4%BB%A3%E7%90%86%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>功能连通的 PV-band 外沿仍可能寿命不够。enclosure 与 tip 是可靠性代理，要写进 LRC。</p><p><span class="marginnote">直觉类比：交三张窗像招人——功能窗是「体检各项正常」（今天能用），随机窗是「不靠运气」（每一颗都稳），可靠性窗是「长期健康」（十年不坏）。三张全过才算合格：前两张绿灯、第三张红字的管芯，探针时看不出任何问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 JEDEC 试验矩阵全文。不把某节点寿命年数当公开规格。封装机械应力只点名与芯片台阶的关系。</p><p>后课默认：寿命把几何代理写进规则与 PV-band。下一课用 TEM/FIB 验证代理是否对应真实剖面。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图形化通过功能测试后仍可在 EM/TDDB/损伤上死。</li><li>enclosure、tip、侧壁是可靠性规则，不只是可印。</li><li>筛选不能替代系统几何修复。</li><li>出处：BEOL EM/TDDB 与几何关系公开讨论；EPE 作为寿命代理。</li></ul>',7))])}const b=B(A,[["render",D]]);export{f as __pageData,b as default};
